def copy_result(result):
    return {key: result[key] for key in result}

def lookup(ledger, request_id, fingerprint):
    entry = ledger.get(request_id)
    if entry is None:
        return None
    if entry["fingerprint"] != fingerprint:
        raise ValueError("request id conflict")
    return copy_result(entry["result"])

def remember(ledger, request_id, fingerprint, result):
    stored = copy_result(result)
    ledger[request_id] = {"fingerprint": fingerprint, "result": stored}
    return copy_result(stored)

