def env_int(value):
    """Parse an ASCII decimal integer after trimming outer whitespace."""
    text = _as_string(value).strip()
    if not text:
        raise ValueError("environment integer is empty")
    for char in text:
        if char < "0" or char > "9":
            raise ValueError("environment integer must contain only ASCII digits")
    return int(text)


def env_bool(value):
    """Parse one of the accepted case-insensitive boolean spellings."""
