        return {"ok": False, "code": "insufficient"}
    state["stock"][sku] -= qty
    state["reservations"][reservation_id] = {"sku": sku, "qty": qty, "refunded": 0}
    return {"ok": True, "reservation_id": reservation_id, "sku": sku, "qty": qty}


