{"path": "parsing.py", "content": """"Parsing helpers for environment-provided configuration values."""


def env_int(value):
    """Parse an environment integer.

    The value must be a string containing only ASCII decimal digits after
    outer whitespace is removed.  Signs, decimal points, underscores, Unicode
    digits and empty strings are rejected.  Leading zeroes are accepted.

    The digits are accumulated manually so that Python's safety limit for
    converting very long strings to ints cannot turn a syntactically valid
    value into an error.
    """
    if not isinstance(value, str):
        raise ValueError("environment integer must be a string")

    text = value.strip()
    if not text:
        raise ValueError("environment integer must not be empty")

    digits = "0123456789"
    number = 0
    for character in text:
        if character not in digits:
            raise ValueError("environment integer contains non-digit characters")
        number = number * 10 + (ord(character) - ord("0"))
    return number


def env_bool(value):
    """Parse one of the accepted environment boolean spellings."""
    if not isinstance(value, str):
        raise ValueError("environment boolean must be a string")

    text = value.strip().lower()
    if text == "true" or text == "1":
        return True
    if text == "false" or text == "0":
        return False
    raise ValueError("environment boolean must be true, false, 1 or 0")
"}

{"path": "overlay.py", "content": """"Structure-aware merging of configuration dictionaries."""

SECTIONS = ("server", "worker", "tags")
FIELDS = {
    "server": ("host", "port", "tls"),
    "worker": ("count", "timeout_ms"),
}


def copy_value(value):
    """Return a detached copy of a JSON-like value."""
    if isinstance(value, dict):
        copied = {}
        for key, item in value.items():
            copied[key] = copy_value(item)
        return copied
    if isinstance(value, list):
        return [copy_value(item) for item in value]
    return value


def merge_config(current, patch):
    """Merge a validated-structure patch into a copy of current.

    Section dictionaries are merged field by field for server and worker, and
    key by key for tags.  Tag values of None remove the corresponding key.
    Leaf values are intentionally not type- or range-checked here; that is
    deferred until all patches and environment overrides have been applied.
    """
    if not isinstance(patch, dict):
        raise ValueError("configuration patch must be a dict")

    result = copy_value(current)

    for section, values in patch.items():
        if not isinstance(section, str):
            raise ValueError("configuration section names must be strings")
        if section not in SECTIONS:
            raise ValueError("unknown configuration section")
        if not isinstance(values, dict):
            raise ValueError("configuration section must be a dict")

        if section in ("server", "worker"):
            allowed = FIELDS[section]
            destination = result[section]
            for field, value in values.items():
                if not isinstance(field, str) or field not in allowed:
                    raise ValueError("unknown field in configuration section")
                destination[field] = copy_value(value)
            continue

        destination = result["tags"]
        for key, value in values.items():
            if not isinstance(key, str) or key == "":
                raise ValueError("tag keys must be nonempty strings")
            if value is None:
                if key in destination:
                    del destination[key]
            elif isinstance(value, str):
                destination[key] = value
            else:
                raise ValueError("tag values must be strings or None")

    return result
"}

{"path": "settings.py", "content": """"Public configuration builder."""

from parsing import env_bool, env_int
from overlay import merge_config

DEFAULTS = {
    "server": {"host": "127.0.0.1", "port": 8080, "tls": False},
    "worker": {"count": 2, "timeout_ms": 5000},
    "tags": {},
}


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _apply_environment(result, environ):
    if not isinstance(environ, dict):
        raise ValueError("environ must be a dict")

    server = result["server"]
    worker = result["worker"]

    if "APP_HOST" in environ:
        value = environ["APP_HOST"]
        if not isinstance(value, str):
            raise ValueError("APP_HOST must be a string")
        server["host"] = value

    if "APP_PORT" in environ:
        server["port"] = env_int(environ["APP_PORT"])

    if "APP_TLS" in environ:
        server["tls"] = env_bool(environ["APP_TLS"])

    if "APP_WORKERS" in environ:
        worker["count"] = env_int(environ["APP_WORKERS"])

    if "APP_TIMEOUT_MS" in environ:
        worker["timeout_ms"] = env_int(environ["APP_TIMEOUT_MS"])


def _validate(result):
    server = result["server"]
    worker = result["worker"]

    host = server["host"]
    if not isinstance(host, str):
        raise ValueError("server.host must be a string")
    host = host.strip()
    if not host:
        raise ValueError("server.host must not be empty")
    server["host"] = host

    port = server["port"]
    if not _is_int(port) or port < 1 or port > 65535:
        raise ValueError("server.port must be an integer in [1, 65535]")

    tls = server["tls"]
    if not isinstance(tls, bool):
        raise ValueError("server.tls must be a bool")

    count = worker["count"]
    if not _is_int(count) or count < 1 or count > 64:
        raise ValueError("worker.count must be an integer in [1, 64]")

    timeout_ms = worker["timeout_ms"]
    if not _is_int(timeout_ms) or timeout_ms < 100 or timeout_ms > 300000:
        raise ValueError("worker.timeout_ms must be an integer in [100, 300000]")

    if tls and port == 80:
        raise ValueError("TLS cannot be enabled on port 80")
    if count * timeout_ms > 600000:
        raise ValueError("worker count and timeout exceed the allowed product")


def build_settings(base, layers, environ):
    """Build, overlay and validate a detached configuration dictionary."""
    if not isinstance(layers, list):
        raise ValueError("layers must be a list")

    result = merge_config(DEFAULTS, base)
    for layer in layers:
        result = merge_config(result, layer)

    _apply_environment(result, environ)
    _validate(result)
    return result
"}

