def env_int(value):
    if not isinstance(value, str):
        raise ValueError("environment integer must be a string")
    text = value.strip()
    if text == "":
        raise ValueError("environment integer must not be empty")
    for ch in text:
        if ch < "0" or ch > "9":
            raise ValueError("environment integer must contain only ASCII digits")

    index = 0
    length = len(text)
    while index < length and text[index] == "0":
        index += 1
    if index == length:
        return 0

    number = 0
    while index < length:
        number = number * 10 + (ord(text[index]) - 48)
        index += 1
    return number


def env_bool(value):
    if not isinstance(value, str):
        raise ValueError("environment boolean must be a string")
    text = value.strip().lower()
    if text == "true" or text == "1":
        return True
    if text == "false" or text == "0":
        return False
    raise ValueError("environment boolean must be true, false, 1, or 0")

